use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    let mut width: int = 0
    let mut ok = false
    let mut rest = ""
    let mut idx = 0
    for line in text.lines() {
        if first {
            first = false
            let t = line.trim()
            let mut valid = t.len() > 0
            for c in t.chars() {
                if c < '0' || c > '9' { valid = false }
            }
            if valid {
                width = t.parse::<int>().unwrap_or(0)
                if width > 0 { ok = true }
            }
        } else {
            rest = rest + line + " "
        }
        idx += 1
    }
    if !ok {
        println("error: bad width")
        std::process::exit(1)
    }
    let mut cur = ""
    let mut curlen: int = 0
    for w in rest.split_whitespace() {
        let wl: int = w.len() as int
        if curlen == 0 {
            cur = w.to_string()
            curlen = wl
        } else if curlen + 1 + wl <= width {
            cur = cur + " " + w
            curlen = curlen + 1 + wl
        } else {
            println("${cur}")
            cur = w.to_string()
            curlen = wl
        }
    }
    if curlen > 0 {
        println("${cur}")
    }
}

